-- ─────────────────────────────────────────────────────────────────────────────
-- vr_measures / vr_measure_issues / vr_positions — Utah 2023GS committee-only measures
-- ─────────────────────────────────────────────────────────────────────────────
-- WHAT THIS ADDS. 68 Utah bills that until now had no measure row at all,
-- with 70 reviewed issue mappings and 607 committee positions across
-- 81 standing-committee actions. Every one of these bills was already in the
-- committee ingest's refusal bucket for 2023GS: a CONTESTED pass-out-favorably vote,
-- confirmed against the published minutes PDF, with every voting name resolved through
-- the reviewed printed-name map — refused only because nobody had reviewed an issue
-- mapping for the parent bill. This pass read the bill text and reviewed them.
--
-- WHERE THE MAPPINGS CAME FROM. db/vr-utah-committee-bills-2023GS.json, one entry per
-- bill, each carrying a direction, a weight, exactly one primary key and prose saying
-- what in the text supports it. 67 of the 135 bills in the bucket are REFUSED in the
-- same file, in writing. No issue key was added to the vocabulary for this pass.
--
-- NO FLOOR VOTES. These measures carry no vr_rollcalls row. A bill reaches this file
-- precisely because it has no admitted floor roll for 2023GS — its floor votes were
-- near-unanimous under the shipped 10%-minority bar, or it never reached a floor vote,
-- or it died in the second chamber. No floor action code was widened and no margin bar
-- was lowered to manufacture one. The consequence is stated rather than hidden:
-- 607 of the 607 positions are the member's ONLY act on that bill and all of them
-- count, because there is no floor vote on these measures for stance-helpers to
-- supersede them with (0 are superseded).
--
-- ACTION TYPE AND WEIGHT ARE UNCHANGED. 'committee_vote' at 0.60 in stance-helpers'
-- act table, printing as "Committee vote", exactly as 20261004000000 wrote it. This
-- file changes no weight, no label, no floor and no threshold.
--
-- THE TIME OF DAY IS NOT KNOWN. The minutes state the meeting's date and do not
-- timestamp the motion, so acted_at is that date at midnight Mountain Standard Time.
--
-- SOURCES. Every measure cites its bill page; every position cites the minutes PDF the
-- act was confirmed against. Each measure's external_ids records which document the
-- mapping was read out of — enrolled text, or the last substitute where the bill never
-- enrolled — so a reader can check the mapping against the same file the curator used.
-- Generated by scripts/vr-utah-committee-mapping.mjs --sql --session 2023GS. Idempotent.
-- ─────────────────────────────────────────────────────────────────────────────

-- HB0027 · H.B. 27 · Drug Possession Penalty Amendments
--   mapping read from the introduced text: https://le.utah.gov/~2023/bills/hbillint/HB0027.htm
--   1 issue mapping(s), 1 committee action(s), 12 position(s)
DO $$
DECLARE m_id integer;
BEGIN
  SELECT id INTO m_id FROM vr_measures
   WHERE number = 'H.B. 27' AND chamber = 'utah house'
     AND external_ids->>'utahSession' = '2023GS' LIMIT 1;
  IF m_id IS NULL THEN
    INSERT INTO vr_measures (measure_type, congress, chamber, number, title,
      short_title, summary, status, source_url, source_label, external_ids)
    VALUES ('bill', NULL, 'utah house', 'H.B. 27', 'Drug Possession Penalty Amendments',
      'Drug Possession Penalty Amendments', 'This bill amends provisions relating to the possession of a weapon.', 'introduced',
      'https://le.utah.gov/~2023/bills/static/HB0027.html', 'Utah State Legislature',
      jsonb_build_object('utahSession', '2023GS', 'utahBill', 'HB0027',
        'primeSponsor', 'BENNIGL', 'floorSponsor', 'WEILET',
        'mappingReadFrom', 'introduced', 'mappingTextUrl', 'https://le.utah.gov/~2023/bills/hbillint/HB0027.htm',
        'committeeOnly', true))
    RETURNING id INTO m_id;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM vr_measure_issues
                  WHERE measure_id = m_id AND issue_key = 'justice_reform') THEN
    INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary,
      support_meaning, rationale, source_url)
    VALUES (m_id, 'justice_reform', 50, true,
      'yea_supports', 'Introduced text rewrites Subsection 76-10-503(3) so that a Category II restricted person who possesses a firearm is guilty of a class A misdemeanor rather than a third degree felony when the only basis for the restriction is unlawful possession of marijuana without intent to produce, manufacture, or dispense it. The operative change is a graded reduction of a criminal penalty, which is what justice_reform carries.', 'https://le.utah.gov/~2023/bills/hbillint/HB0027.htm');
  END IF;
  -- 2023-01-20 · House Law Enforcement and Criminal Justice Standing Committee · Rep. Stoddard moved to pass H.B. 27 out favorably.
