-- HB0054 · H.B. 54 · Tax Revisions
--   mapping read from the enrolled text: https://le.utah.gov/~2023/bills/hbillenr/HB0054.htm
--   2 issue mapping(s), 1 committee action(s), 5 position(s)
DO $$
DECLARE m_id integer;
BEGIN
  SELECT id INTO m_id FROM vr_measures
   WHERE number = 'H.B. 54' AND chamber = 'utah house'
     AND external_ids->>'utahSession' = '2023GS' LIMIT 1;
  IF m_id IS NULL THEN
    INSERT INTO vr_measures (measure_type, congress, chamber, number, title,
      short_title, summary, status, source_url, source_label, external_ids)
    VALUES ('bill', NULL, 'utah house', 'H.B. 54', 'Tax Revisions',
      'Tax Revisions', 'This bill modifies state tax provisions.', 'enacted',
      'https://le.utah.gov/~2023/bills/static/HB0054.html', 'Utah State Legislature',
      jsonb_build_object('utahSession', '2023GS', 'utahBill', 'HB0054',
        'primeSponsor', 'ELIASS', 'floorSponsor', 'MCCAYD',
        'mappingReadFrom', 'enrolled', 'mappingTextUrl', 'https://le.utah.gov/~2023/bills/hbillenr/HB0054.htm',
        'committeeOnly', true))
    RETURNING id INTO m_id;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM vr_measure_issues
                  WHERE measure_id = m_id AND issue_key = 'lower_taxes') THEN
    INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary,
      support_meaning, rationale, source_url)
    VALUES (m_id, 'lower_taxes', 85, true,
      'yea_supports', 'Enrolled text cuts the individual income tax rate and the corporate franchise tax rate, and removes the state sales and use tax on food and food ingredients contingent on a constitutional amendment. Three separate rate or base reductions in one instrument, all in the same direction, make this the clearest tax-cut vote in the 2023 committee bucket.', 'https://le.utah.gov/~2023/bills/hbillenr/HB0054.htm');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM vr_measure_issues
                  WHERE measure_id = m_id AND issue_key = 'tax_middle_class') THEN
    INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary,
      support_meaning, rationale, source_url)
    VALUES (m_id, 'tax_middle_class', 45, false,
      'yea_supports', 'The same enrolled text also expands the state earned income tax credit and raises the income phase-out thresholds on the social security benefits credit. These are distinct provisions from the rate cuts and they target lower and middle income filers specifically rather than all filers, so they earn a second, narrower key.', 'https://le.utah.gov/~2023/bills/hbillenr/HB0054.htm');
  END IF;
  -- 2023-02-21 · House Revenue and Taxation Standing Committee · Rep. Christofferson moved to pass 1st Substitute H.B. 54 out favorably.
  --   printed tally 9-2-2 (yea-nay-absent); 5 named voter(s) on the PolitiDex roster
