    INSERT INTO vr_measures (measure_type, congress, chamber, number, title,
      short_title, summary, status, source_url, source_label, external_ids)
    VALUES ('bill', NULL, 'utah house', 'H.B. 64', 'Waiver of Punitive Damages Amendments',
      'Waiver of Punitive Damages Amendments', 'This bill addresses agreements to waive or limit liability for punitive damages.', 'introduced',
