-- HB0144 · H.B. 144 · High Cost Infrastructure Development Tax Credit Amendments
--   mapping read from the enrolled text: https://le.utah.gov/~2023/bills/hbillenr/HB0144.htm
--   1 issue mapping(s), 1 committee action(s), 4 position(s)
DO $$
DECLARE m_id integer;
BEGIN
  SELECT id INTO m_id FROM vr_measures
   WHERE number = 'H.B. 144' AND chamber = 'utah house'
     AND external_ids->>'utahSession' = '2023GS' LIMIT 1;
  IF m_id IS NULL THEN
    INSERT INTO vr_measures (measure_type, congress, chamber, number, title,
      short_title, summary, status, source_url, source_label, external_ids)
    VALUES ('bill', NULL, 'utah house', 'H.B. 144', 'High Cost Infrastructure Development Tax Credit Amendments',
      'High Cost Infrastructure Development Tax Credit Amendments', 'This bill modifies the high cost infrastructure development tax credit.', 'enacted',
      'https://le.utah.gov/~2023/bills/static/HB0144.html', 'Utah State Legislature',
      jsonb_build_object('utahSession', '2023GS', 'utahBill', 'HB0144',
        'primeSponsor', 'ALBRECR', 'floorSponsor', 'OWENSD',
        'mappingReadFrom', 'enrolled', 'mappingTextUrl', 'https://le.utah.gov/~2023/bills/hbillenr/HB0144.htm',
        'committeeOnly', true))
    RETURNING id INTO m_id;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM vr_measure_issues
                  WHERE measure_id = m_id AND issue_key = 'energy_production') THEN
    INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary,
      support_meaning, rationale, source_url)
    VALUES (m_id, 'energy_production', 65, true,
      'yea_supports', 'Enrolled text extends the high cost infrastructure development tax credit and broadens the eligible project definition to include the storage or production of all fuels and infrastructure for an underground mine. Widening a production tax credit from a narrow list of fuels to all fuels, plus mine infrastructure, is a direct subsidy for extraction and fuel production capacity.', 'https://le.utah.gov/~2023/bills/hbillenr/HB0144.htm');
  END IF;
