-- HB0147 · H.B. 147 · Crime Posting Restrictions
--   mapping read from the introduced text: https://le.utah.gov/~2023/bills/hbillint/HB0147.htm
--   2 issue mapping(s), 1 committee action(s), 10 position(s)
DO $$
DECLARE m_id integer;
BEGIN
  SELECT id INTO m_id FROM vr_measures
   WHERE number = 'H.B. 147' AND chamber = 'utah house'
     AND external_ids->>'utahSession' = '2023GS' LIMIT 1;
  IF m_id IS NULL THEN
    INSERT INTO vr_measures (measure_type, congress, chamber, number, title,
      short_title, summary, status, source_url, source_label, external_ids)
    VALUES ('bill', NULL, 'utah house', 'H.B. 147', 'Crime Posting Restrictions',
      'Crime Posting Restrictions', 'This bill identifies circumstances where it is a crime to fail to aid a crime victim.', 'introduced',
      'https://le.utah.gov/~2023/bills/static/HB0147.html', 'Utah State Legislature',
      jsonb_build_object('utahSession', '2023GS', 'utahBill', 'HB0147',
        'primeSponsor', 'KINGBS', 'floorSponsor', NULL,
        'mappingReadFrom', 'introduced', 'mappingTextUrl', 'https://le.utah.gov/~2023/bills/hbillint/HB0147.htm',
        'committeeOnly', true))
    RETURNING id INTO m_id;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM vr_measure_issues
                  WHERE measure_id = m_id AND issue_key = 'tough_on_crime') THEN
    INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary,
      support_meaning, rationale, source_url)
    VALUES (m_id, 'tough_on_crime', 55, true,
      'yea_supports', 'Introduced text makes it a criminal offense to fail to render reasonable assistance to a victim of a crime the person witnesses, and imposes penalties. It creates a new affirmative criminal duty backed by punishment where none existed, which is squarely the tough_on_crime direction.', 'https://le.utah.gov/~2023/bills/hbillint/HB0147.htm');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM vr_measure_issues
                  WHERE measure_id = m_id AND issue_key = 'free_speech') THEN
    INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary,
      support_meaning, rationale, source_url)
    VALUES (m_id, 'free_speech', 45, false,
      'yea_opposes', 'A separate provision of the same introduced text prohibits a person from distributing a visual recording of a crime unless the person first reported the crime to law enforcement. That is a distinct provision from the duty-to-assist offense and it restricts publication of a recording rather than conduct at the scene, so it earns a second, narrow key against free_speech.', 'https://le.utah.gov/~2023/bills/hbillint/HB0147.htm');
  END IF;
  -- 2023-02-15 · House Judiciary Standing Committee · Rep. Clancy moved to pass H.B. 147 out favorably.
