   WHERE number = 'H.B. 329' AND chamber = 'utah house'
     AND external_ids->>'utahSession' = '2023GS' LIMIT 1;
  IF m_id IS NULL THEN
    INSERT INTO vr_measures (measure_type, congress, chamber, number, title,
      short_title, summary, status, source_url, source_label, external_ids)
    VALUES ('bill', NULL, 'utah house', 'H.B. 329', 'Event Permit Notification Amendments',
      'Event Permit Notification Amendments', 'This bill requires a public entity to provide public notice for a permitted event with an adult theme.', 'introduced',
