    VALUES (m_id, 'free_speech', 55, true,
      'yea_opposes', 'Third substitute text requires a public entity that issues a permit for an event with an adult theme to give public notice under defined conditions and sets out liability presumptions and limitations tied to that notice. Attaching a notice condition and a liability regime to a permit based on the expressive content of the event burdens the expression, so a yea is a vote against free_speech.', 'https://le.utah.gov/~2023/bills/hbillint/HB0329S03.htm');
