-- HB0534 · H.B. 534 · Telemedicine Amendments
--   mapping read from the introduced text: https://le.utah.gov/~2023/bills/hbillint/HB0534.htm
--   1 issue mapping(s), 1 committee action(s), 10 position(s)
DO $$
DECLARE m_id integer;
BEGIN
  SELECT id INTO m_id FROM vr_measures
   WHERE number = 'H.B. 534' AND chamber = 'utah house'
     AND external_ids->>'utahSession' = '2023GS' LIMIT 1;
  IF m_id IS NULL THEN
    INSERT INTO vr_measures (measure_type, congress, chamber, number, title,
      short_title, summary, status, source_url, source_label, external_ids)
    VALUES ('bill', NULL, 'utah house', 'H.B. 534', 'Telemedicine Amendments',
      'Telemedicine Amendments', 'This bill amends provisions relating to reimbursement for telemedicine services.', 'introduced',
      'https://le.utah.gov/~2023/bills/static/HB0534.html', 'Utah State Legislature',
      jsonb_build_object('utahSession', '2023GS', 'utahBill', 'HB0534',
        'primeSponsor', 'BALLAMG', 'floorSponsor', 'KENNEMS',
        'mappingReadFrom', 'introduced', 'mappingTextUrl', 'https://le.utah.gov/~2023/bills/hbillint/HB0534.htm',
        'committeeOnly', true))
    RETURNING id INTO m_id;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM vr_measure_issues
                  WHERE measure_id = m_id AND issue_key = 'healthcare') THEN
    INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary,
      support_meaning, rationale, source_url)
    VALUES (m_id, 'healthcare', 50, true,
      'yea_supports', 'Introduced text requires a health insurer to reimburse a network provider for a telemedicine service at 90% or more of the rate paid for the equivalent in-person service when that provider also delivers the service in person in the state. A payment-parity floor is what determines whether providers offer telemedicine at all, so the mandate expands access to covered care.', 'https://le.utah.gov/~2023/bills/hbillint/HB0534.htm');
