-- ── VERIFICATION ────────────────────────────────────────────────────────────
-- Fails loudly rather than leaving a half-written committee record behind. This
-- lane only: 2023GS measures carrying committeeOnly. The seed-lane migration's
-- own guard excludes exactly these rows, so neither file asserts the other's total.
DO $$
DECLARE n_pos integer; n_measures integer; n_issues integer; n_floorish integer; n_nosrc integer;
BEGIN
  SELECT count(*) INTO n_pos FROM vr_positions p
    JOIN vr_measures m ON m.id = p.measure_id
   WHERE p.action_type = 'committee_vote'
     AND m.external_ids->>'utahSession' = '2023GS'
     AND (m.external_ids->>'committeeOnly') = 'true'
  ;
  IF n_pos <> 607 THEN
    RAISE EXCEPTION 'expected 607 Utah 2023GS mapping-lane committee_vote positions, found %', n_pos;
  END IF;
  SELECT count(DISTINCT p.measure_id) INTO n_measures FROM vr_positions p
    JOIN vr_measures m ON m.id = p.measure_id
   WHERE p.action_type = 'committee_vote'
     AND m.external_ids->>'utahSession' = '2023GS'
     AND (m.external_ids->>'committeeOnly') = 'true'
  ;
  IF n_measures <> 68 THEN
    RAISE EXCEPTION 'expected 68 bills with Utah 2023GS mapping-lane committee votes, found %', n_measures;
  END IF;
  -- Every one of these measures exists only because a curator reviewed a mapping
  -- for it; a committee-only measure with no issue row would be a vote with no
  -- direction, which is the thing this lane refuses to publish.
  SELECT count(*) INTO n_issues FROM vr_measure_issues i
    JOIN vr_measures m ON m.id = i.measure_id
   WHERE true
     AND m.external_ids->>'utahSession' = '2023GS'
     AND (m.external_ids->>'committeeOnly') = 'true'
  ;
  IF n_issues <> 70 THEN
    RAISE EXCEPTION 'expected 70 reviewed issue mappings on Utah 2023GS mapping-lane measures, found %', n_issues;
  END IF;
  -- A committee act must never have been written as a roll call.
  SELECT count(*) INTO n_floorish FROM vr_rollcalls r
    JOIN vr_measures m ON m.id = r.measure_id
   WHERE true
     AND m.external_ids->>'utahSession' = '2023GS'
     AND (m.external_ids->>'committeeOnly') = 'true'
  ;
  IF n_floorish > 0 THEN
    RAISE EXCEPTION 'a committee vote reached vr_rollcalls (% rows)', n_floorish;
  END IF;
  -- Every act carries the published minutes PDF it was confirmed against.
  SELECT count(*) INTO n_nosrc FROM vr_positions p
    JOIN vr_measures m ON m.id = p.measure_id
   WHERE p.action_type = 'committee_vote'
     AND m.external_ids->>'utahSession' = '2023GS'
     AND (m.external_ids->>'committeeOnly') = 'true'
     AND (p.source_url IS NULL OR p.source_url NOT LIKE 'https://le.utah.gov/%.pdf')
  ;
  IF n_nosrc > 0 THEN
    RAISE EXCEPTION '% committee votes without a minutes PDF citation', n_nosrc;
  END IF;
END $$;

